## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as databricks from "@pulumi/databricks";

const ldpDemo = new databricks.Notebook("ldp_demo", {});
const ldpDemoRepo = new databricks.Repo("ldp_demo", {});
const _this = new databricks.Pipeline("this", {
    name: "Pipeline Name",
    catalog: "main",
    schema: "ldp_demo",
    configuration: {
        key1: "value1",
        key2: "value2",
    },
    clusters: [
        {
            label: "default",
            numWorkers: 2,
            customTags: {
                cluster_type: "default",
            },
        },
        {
            label: "maintenance",
            numWorkers: 1,
            customTags: {
                cluster_type: "maintenance",
            },
        },
    ],
    libraries: [
        {
            notebook: {
                path: ldpDemo.id,
            },
        },
        {
            file: {
                path: pulumi.interpolate`${ldpDemoRepo.path}/pipeline.sql`,
            },
        },
        {
            glob: {
                include: pulumi.interpolate`${ldpDemoRepo.path}/subfolder/**`,
            },
        },
    ],
    continuous: false,
    notifications: [{
        emailRecipients: [
            "user@domain.com",
            "user1@domain.com",
        ],
        alerts: [
            "on-update-failure",
            "on-update-fatal-failure",
            "on-update-success",
            "on-flow-failure",
        ],
    }],
});
